def backend_entry(fetch_models, ui_url):
    entry = {"name": "invokeai"}
    try:
        entry["models"] = list(fetch_models())
    except RuntimeError as exc:
        entry["models_error"] = str(exc)
        return entry
    entry["model_management"] = {"ui_url": ui_url}
    return entry

