import unittest

from catalog import backend_entry


class CatalogTests(unittest.TestCase):
    def test_success_exposes_management(self):
        entry = backend_entry(lambda: ["a"], "http://invokeai/ui")
        self.assertEqual(entry["models"], ["a"])
        self.assertEqual(entry["model_management"]["ui_url"], "http://invokeai/ui")

    def test_failure_still_exposes_management(self):
        def fail():
            raise RuntimeError("catalog unavailable")

        entry = backend_entry(fail, "http://invokeai/ui")
        self.assertEqual(entry["models_error"], "catalog unavailable")
        self.assertEqual(entry["model_management"]["ui_url"], "http://invokeai/ui")


if __name__ == "__main__":
    unittest.main()
